'use strict';

// MODULES //

var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var format = require( '@stdlib/string/format' );
var isNorm = require( './is_norm.js' );
var base = require( './base.js' );


// MAIN //

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real tridiagonal matrix `A`.
*
* ## Notes
*
* -   `norm` must be one of the following: `'M'` or `'m'` (largest absolute value of any element), `'1'`, `'O'`, or `'o'` (one norm), `'I'` or `'i'` (infinity norm), and `'F'`, `'f'`, `'E'`, or `'e'` (Frobenius norm).
* -   `DL` should have `N-1` indexed elements.
* -   `D` should have `N` indexed elements.
* -   `DU` should have `N-1` indexed elements.
*
* @param {string} norm - specifies the norm to be computed
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {Float64Array} DL - the first sub-diagonal of `A`
* @param {integer} strideDL - stride length for `DL`
* @param {Float64Array} D - the diagonal of `A`
* @param {integer} strideD - stride length for `D`
* @param {Float64Array} DU - the first super-diagonal of `A`
* @param {integer} strideDU - stride length for `DU`
* @throws {TypeError} first argument must be a valid norm
* @returns {number} matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var D = new Float64Array( [ 4.0, 5.0, 6.0, 7.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0, 1.0 ] );
*
* var norm = dlangt( 'M', 4, DL, 1, D, 1, DU, 1 );
* // returns 7.0
*/
function dlangt( norm, N, DL, strideDL, D, strideD, DU, strideDU ) {
	if ( !isNorm( norm ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid norm type. Value: `%s`.', norm ) );
	}
	if ( N <= 0 ) {
		return 0.0;
	}
	return base( norm, N, DL, strideDL, stride2offset( N - 1, strideDL ), D, strideD, stride2offset( N, strideD ), DU, strideDU, stride2offset( N - 1, strideDU ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = dlangt;
